// New: maps a data type to the IR type stored in symbols. It is half of the
// private mapping between type annotations, AstDataType and IrType; the other
// directions arrive with the tickets that need them.
static IrType data_type_to_ir(Ctx* ctx, AstDataType type) {
  switch (type) {
    case AST_DATA_TYPE_INT:
      return IR_INT;
    case AST_DATA_TYPE_DOUBLE:
      return IR_DOUBLE;
    case AST_DATA_TYPE_BOOLEAN:
      return IR_BOOL;
    case AST_DATA_TYPE_STRING:
      return IR_STRING;
    case AST_DATA_TYPE_UNIT:
      return IR_UNIT;
    case AST_DATA_TYPE_UNKNOWN:
      break;
  }
  THROW(E_INTERNAL_ERROR, "semantic analysis met an expression without a type");
  return IR_UNIT;
}

