// Changes:
// New: "widen into position" helper for the typing, calls and for-loop tickets.
// The (already checked) expression at index of parent must be usable where
// target is required: the same type passes, an Int is widened when target is
// Double, anything else stops with code (6 for values, 5 for call arguments).
// what names the construct in the message.
static void require_compatible(Ctx* ctx,
                               AstNode* parent,
                               size_t index,
                               AstDataType target,
                               ExitCode code,
                               const char* what) {
  AstNode* child = NULL;
  ast_node_get_child(ctx, parent, index, &child);
  AstDataType actual = expr_type(ctx, child);
  if (!is_compatible(actual, target))
    THROW(code, "%s at %d:%d needs %s but the value is %s", what,
          ast_node_get_line(child), ast_node_get_column(child),
          data_type_name(target), data_type_name(actual));
  if (actual == AST_DATA_TYPE_INT && target == AST_DATA_TYPE_DOUBLE)
    widen_child(ctx, parent, index);
}

