// the caller fills it and inserts without anything that can THROW in between.
static SymtableData function_data(Ctx* ctx,
                                  IrType return_type,
                                  size_t ir_index,
                                  size_t param_count) {
  SymtableData data = {
      .symbol_type = SYMBOL_FUNCTION,
      .ir_type = return_type,
      .ir_index = ir_index,
      .param_count = param_count,
      .param_types = NULL,
      .is_val = false,
  };
  if (param_count > 0)
    data.param_types = TRY_MALLOC(sizeof(IrType) * param_count);
  return data;
}

// AI generated by: Claude Code (claude-sonnet-5-5)
// Prompt: "implementation done using skill: mattpocock-skills:implement-spec,
// ticket 02: tracer, semantic entry point, member entries and function
// collection"
// Changes:
// New: phase 0, the eight member entries (ADR-0002 and its amendment). The key
// is "<ReceiverType>.<member>", the receiver is the only parameter, the IR
// function type goes to ir_index like for a built-in.
static void insert_members(Ctx* ctx, Sema* sema) {
  static const struct {
    const char* key;
    IrType receiver;
    IrType result;
    IrFunctionType function;
  } members[] = {
      {"Int.toString", IR_INT, IR_STRING, IR_FX_TO_STR},
      {"Double.toString", IR_DOUBLE, IR_STRING, IR_FX_TO_STR},
      {"Boolean.toString", IR_BOOL, IR_STRING, IR_FX_TO_STR},
      {"String.toString", IR_STRING, IR_STRING, IR_FX_TO_STR},
      {"Unit.toString", IR_UNIT, IR_STRING, IR_FX_TO_STR},
      {"Double.toInt", IR_DOUBLE, IR_INT, IR_FX_TO_INT},
      // The IR has a floor instruction instead of a function, ir_index is
      // unused and IR generation recognises the member by its name
      {"Double.floor", IR_DOUBLE, IR_DOUBLE, IR_FX_USER},
      {"String.length", IR_STRING, IR_INT, IR_FX_STR_LEN},
  };
  for (size_t i = 0; i < sizeof(members) / sizeof(members[0]); i++) {
    SymtableData data = function_data(ctx, members[i].result,
                                      (size_t)members[i].function, 1);
    data.param_types[0] = members[i].receiver;
    symtable_insert(ctx, sema->scope, (char*)members[i].key, data);
  }
}

// AI generated by: Claude Code (claude-sonnet-5-5)
// Prompt: "implementation done using skill: mattpocock-skills:implement-spec,
// ticket 02: tracer, semantic entry point, member entries and function
// collection"
// Changes:
// New: declares one DEF as a function symbol of the global scope and points
// its identifier at it. A name already in the global scope, built-ins
// included, is a redefinition (exit 4). Members cannot clash, their keys
// contain a dot. The return type is a Unit placeholder until a later ticket
// infers it. A @main with a parameter is exit 5.
static void collect_function(Ctx* ctx, Sema* sema, AstNode* def, size_t id) {
  AstNode* ident = NULL;
  ast_node_get_child(ctx, def, DEF_IDENT, &ident);
  const char* name = ast_node_get_name(ident);

  if (symtable_lookup(sema->scope, (char*)name, false) != NULL)
    THROW(E_SEMANTIC_REDEFINITION_ERROR,
          "redefinition of function '%s' at %d:%d", name,
          ast_node_get_line(ident), ast_node_get_column(ident));

  AstNode* rettype = NULL;
  ast_node_get_child(ctx, def, DEF_RETTYPE, &rettype);
  IrType return_type = IR_UNIT;
  if (ast_node_get_type(rettype) != AST_NODE_NONE)
    return_type = annotation_to_ir(ctx, rettype);

  AstNode* params = NULL;
  size_t param_count = 0;
  if (ast_node_get_child_count(def) > DEF_PARAM_LIST) {
    ast_node_get_child(ctx, def, DEF_PARAM_LIST, &params);
    param_count = ast_node_get_child_count(params);
  }

  if ((ast_node_get_flags(def) & (unsigned)AST_FLAG_MAIN) && param_count > 0)
    THROW(E_SEMANTIC_ARGUMENT_ERROR,
          "@main function '%s' at %d:%d must not have parameters", name,
          ast_node_get_line(ident), ast_node_get_column(ident));

  // Check every parameter type before allocating the array, so a THROW here
  // has nothing to free
  for (size_t i = 0; i < param_count; i++) {
    AstNode* param = NULL;
    AstNode* type = NULL;
    ast_node_get_child(ctx, params, i, &param);
    ast_node_get_child(ctx, param, 1, &type);
    (void)annotation_to_ir(ctx, type);
  }
  SymtableData data = function_data(ctx, return_type, id, param_count);
  for (size_t i = 0; i < param_count; i++) {
    AstNode* param = NULL;
    AstNode* type = NULL;
    ast_node_get_child(ctx, params, i, &param);
    ast_node_get_child(ctx, param, 1, &type);
    data.param_types[i] = annotation_to_ir(ctx, type);
  }

  symtable_insert(ctx, sema->scope, (char*)name, data);
  ast_node_set_symbol(ident, symtable_lookup(sema->scope, (char*)name, false));
}

// AI generated by: Claude Code (claude-sonnet-5-5)
// Prompt: "implementation done using skill: mattpocock-skills:implement-spec,
// ticket 02: tracer, semantic entry point, member entries and function
// collection"
// Changes:
// New: phase 1, function collection. Every DEF of the PROGRAM in source order
// becomes a function symbol, its function id is its position among the
// PROGRAM's children. Afterwards checks @main: none is exit 3, more than one
// exit 4 (the Unit return type check comes with the return type ticket).
static void collect_functions(Ctx* ctx, Sema* sema) {
  size_t mains = 0;
  size_t count = ast_node_get_child_count(sema->program);
  for (size_t id = 0; id < count; id++) {
    AstNode* def = NULL;
    ast_node_get_child(ctx, sema->program, id, &def);
    if (ast_node_get_type(def) != AST_NODE_DEF)
      THROW(E_INTERNAL_ERROR, "unexpected top-level node at %d:%d",
            ast_node_get_line(def), ast_node_get_column(def));

    // AI generated by: Claude Code (claude-opus-5-5)
    // Prompt: "implementation done using skill:
    // mattpocock-skills:implement-spec, ticket 02: tracer, semantic entry
    // point, member entries and function collection"
    // Changes:
    // Review fix: a second @main is exit 4 even when it also has a parameter
    // (exit 5), so it is counted before the function is collected
    if (ast_node_get_flags(def) & (unsigned)AST_FLAG_MAIN) {
      mains++;
      if (mains > 1) {
        AstNode* ident = NULL;
        ast_node_get_child(ctx, def, DEF_IDENT, &ident);
        THROW(E_SEMANTIC_REDEFINITION_ERROR,
              "more than one @main function, second one '%s' at %d:%d",
              ast_node_get_name(ident), ast_node_get_line(ident),
              ast_node_get_column(ident));
      }
    }

    collect_function(ctx, sema, def, id);
  }
  if (mains == 0)
    THROW(E_SEMANTIC_UNDEFINED_ERROR, "no @main function in the program");
}

